func TestCreateEntryCreatesFile(t *testing.T) {
	root := t.TempDir()
	handler := NewFileHandler(root, []string{".go"})

	recorder := postJSON(t, handler.CreateEntry, map[string]string{"path": "main.go", "type": "file"})
	if recorder.Code != http.StatusOK {
		t.Fatalf("status=%d body=%s", recorder.Code, recorder.Body.String())
	}
}

func (h *WidgetsHandler) HandleListWidgets(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	widgets, err := h.db.ListWidgets()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(map[string]any{"widgets": widgets})
}
